#include <Arduino.h>
#include <WiFi.h>
#include <HTTPClient.h>
#include <WiFiManager.h>

// ============================================================================
// KOMPLETNA NADPISANIE PARAMETRÓW EKRANU DLA LILYGO T-EMBED (Wszystkie wersje)
// ============================================================================
#define USER_SETUP_LOADED 1
#define ST7789_DRIVER     1  // Sterownik ekranu T-Embed
#define TFT_RGB_ORDER     TFT_BGR // Wyświetlacze LilyGo często wymagają zamiany kolorów
#define TFT_WIDTH         170
#define TFT_HEIGHT        320

// Oficjalne piny magistrali SPI ekranu w T-Embed
#define TFT_MOSI          9
#define TFT_SCLK          10
#define TFT_CS            41
#define TFT_DC            16
#define TFT_RST           -1  // Ekran nie ma pinu sprzętowego resetu

#define LOAD_GLCD         1  // Załadowanie podstawowej czcionki systemowej
#define SPI_FREQUENCY     27000000

#include <TFT_eSPI.h>

// DEFINICJE PINÓW ZASILANIA DLA OBU REWIZJI T-EMBED
#define PIN_POWER_ON_V1   15
#define PIN_LCD_BL_V1     21

#define PIN_POWER_ON_V2   46
#define PIN_LCD_BL_V2     15

TFT_eSPI tft = TFT_eSPI();

struct MeterData {
    String id = "N/A";
    String serial = "N/A";
    String usage = "N/A";
};

void updateScreen(String status, MeterData meter) {
    tft.fillScreen(TFT_BLACK);
    tft.drawRect(0, 0, tft.width(), tft.height(), TFT_CYAN);

    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(2);
    tft.setCursor(15, 15);
    tft.print("WMBUS DECODER");

    tft.setTextSize(1);
    tft.setTextColor(TFT_YELLOW, TFT_BLACK);
    tft.setCursor(15, 45);
    tft.print("Status: " + status);

    tft.setTextSize(2);
    tft.setTextColor(TFT_GREEN, TFT_BLACK);
    tft.setCursor(15, 70);
    tft.print("ID: " + meter.id);

    tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
    tft.setCursor(15, 100);
    tft.print("SERIAL: " + meter.serial);

    tft.setTextColor(TFT_ORANGE, TFT_BLACK);
    tft.setCursor(15, 130);
    tft.print("ODCZYT: " + meter.usage);
}

void setup() {
    Serial.begin(115200);
    delay(1000); 

    Serial.println("--- START URUCHAMIANIA HARDWARE ---");

    // AKTYWACJA ZASILANIA DLA REWIZJI 1 (GPIO 15)
    pinMode(PIN_POWER_ON_V1, OUTPUT);
    digitalWrite(PIN_POWER_ON_V1, HIGH);

    // AKTYWACJA ZASILANIA DLA REWIZJI 2 (GPIO 46)
    pinMode(PIN_POWER_ON_V2, OUTPUT);
    digitalWrite(PIN_POWER_ON_V2, HIGH);

    // Uruchomienie podświetlenia na wszystkich możliwych pinach (GPIO 21 oraz GPIO 15)
    pinMode(PIN_LCD_BL_V1, OUTPUT);
    digitalWrite(PIN_LCD_BL_V1, HIGH);

    pinMode(PIN_LCD_BL_V2, OUTPUT);
    digitalWrite(PIN_LCD_BL_V2, HIGH);

    delay(500); // Czas na start przetwornicy napięcia ekranu

    // Inicjalizacja ekranu
    tft.init();
    tft.setRotation(3); // Pozycja pozioma

    // Kluczowe komendy dla ekranu ST7789 w urządzeniach LilyGo:
    tft.writecommand(0x21); // Włączenie inwersji kolorów (Display Inversion ON)

    tft.fillScreen(TFT_BLACK); 

    // Wyświetlenie komunikatu testowego
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(2);
    tft.setCursor(15, 40);
    tft.println("WIFI MANAGER START");
    tft.setTextSize(1);
    tft.setCursor(15, 75);
    tft.println("Szukaj sieci: T-Embed-WiFi");

    Serial.println("Uruchamianie portalu WiFiManager...");

    WiFiManager wm;
    wm.setConfigPortalTimeout(180); // Portal aktywny przez 3 minuty

    if (!wm.autoConnect("T-Embed-WiFi")) {
        Serial.println("Nie wprowadzono danych Wi-Fi w wyznaczonym czasie.");
    } else {
        Serial.println("Sukces: ESP32 polaczony z routerem!");
    }

    MeterData startData;
    updateScreen("System gotowy do pracy", startData);
}

void loop() {
    // Program wchodzi w pętlę i czeka na dane
    delay(1000);
}
